SELECT COUNT(*) FROM training_booking
WHERE student_user_id = #{studentUserId}
  AND status IN ('PENDING', 'ASSIGNED', 'COMPLETED')
  AND planned_start < #{plannedEnd}
  AND planned_end > #{plannedStart}

SELECT COUNT(*) FROM training_booking
WHERE coach_user_id = #{coachUserId}
  AND status IN ('PENDING', 'ASSIGNED', 'COMPLETED')
  AND planned_start < #{plannedEnd}
  AND planned_end > #{plannedStart}

SELECT COUNT(*) FROM training_booking
WHERE vehicle_id = #{vehicleId}
  AND status IN ('PENDING', 'ASSIGNED', 'COMPLETED')
  AND planned_start < #{plannedEnd}
  AND planned_end > #{plannedStart}
